using Wip.Bones.Domain;
using Wip.Bones.Engine;
using System.Collections.Generic;
using System.Linq;

public sealed class SeatStrategy : IBonesPlayerSlot
{
    public BonesMove ChooseMove(BonesRoundState state, IReadOnlyList<BonesMove> legalMoves)
    {
        if (legalMoves.Count == 0)
            throw new System.InvalidOperationException("No legal moves.");

        var board = state.Board;
        var hand = state.Hands.GetHand(state.CurrentPlayer);
        int leftEndPip = board.LeftEnd?.Pip.Value ?? -1;
        int rightEndPip = board.RightEnd?.Pip.Value ?? -1;

        // Count pip frequencies in hand
        int[] pipCounts = new int[7];
        foreach (var t in hand.Tiles)
        {
            pipCounts[t.LowPip.Value]++;
            if (!t.IsDouble)
                pipCounts[t.HighPip.Value]++;
        }

        int handTileCount = hand.Tiles.Length;
        bool isEndgame = handTileCount <= 3;

        BonesMove? bestMove = null;
        int bestScore = int.MinValue;

        foreach (var move in legalMoves)
        {
            if (move.IsPass)
            {
                if (bestMove == null)
                {
                    bestMove = move;
                    bestScore = -10000;
                }
                continue;
            }

            var tile = move.Tile!.Value;
            int score = 0;

            // Strong bonus for doubles: blocking power and flexibility
            if (tile.IsDouble)
                score += 70;

            // Prefer high total pips to shed large tiles
            score += tile.TotalPips * 4;

            // Check if tile matches board ends
            bool matchesLeft = leftEndPip >= 0 && (tile.LowPip.Value == leftEndPip || tile.HighPip.Value == leftEndPip);
            bool matchesRight = rightEndPip >= 0 && (tile.LowPip.Value == rightEndPip || tile.HighPip.Value == rightEndPip);

            // Strong preference for moves that match a board end
            if (matchesLeft || matchesRight)
                score += 80;
            else if (board.Tiles.Length > 0)
                score -= 100;

            // Prefer playing on the side that matches our stronger pip holdings
            if (matchesLeft)
            {
                int leftPipCount = pipCounts[leftEndPip];
                score += leftPipCount * 8;
                if (move.Side == BonesBoardSide.Left)
                    score += 20;
            }
            if (matchesRight)
            {
                int rightPipCount = pipCounts[rightEndPip];
                score += rightPipCount * 8;
                if (move.Side == BonesBoardSide.Right)
                    score += 20;
            }

            // Heavily penalize playing a tile that would leave us with no matching ends
            if (leftEndPip >= 0 || rightEndPip >= 0)
            {
                int remainingMatching = CountMatchingAfterPlay(hand, tile, leftEndPip, rightEndPip);
                if (remainingMatching == 0)
                    score -= 200;
            }

            // Bonus for playing a tile that matches pips we hold many of (future options)
            int lowPipCount = pipCounts[tile.LowPip.Value];
            int highPipCount = tile.IsDouble ? 0 : pipCounts[tile.HighPip.Value];
            score += (lowPipCount + highPipCount) * 6;

            // Prefer playing on the side that balances chain length
            if (matchesLeft && matchesRight)
            {
                int leftChainCount = 0, rightChainCount = 0;
                foreach (var chainTile in board.Tiles)
                {
                    if (chainTile.ChainLeftPip.Value == leftEndPip)
                        leftChainCount++;
                    if (chainTile.ChainRightPip.Value == rightEndPip)
                        rightChainCount++;
                }
                if (leftChainCount < rightChainCount && move.Side == BonesBoardSide.Left)
                    score += 30;
                else if (rightChainCount < leftChainCount && move.Side == BonesBoardSide.Right)
                    score += 30;
            }

            // Penalty for playing a double when we have many of that pip (risk of being stuck)
            if (tile.IsDouble)
            {
                int otherPip = tile.LowPip.Value;
                if (pipCounts[otherPip] >= 3)
                    score -= 50;
            }

            // In endgame, prioritize playing tiles that match our most common pip to avoid being blocked
            if (isEndgame)
            {
                int maxPipCount = 0;
                for (int i = 0; i < 7; i++)
                {
                    if (pipCounts[i] > maxPipCount)
                        maxPipCount = pipCounts[i];
                }
                if (lowPipCount == maxPipCount || highPipCount == maxPipCount)
                    score += 40;

                // Extra penalty for playing a tile that would leave us without matching ends in endgame
                if (leftEndPip >= 0 || rightEndPip >= 0)
                {
                    int remainingMatching = CountMatchingAfterPlay(hand, tile, leftEndPip, rightEndPip);
                    if (remainingMatching == 0)
                        score -= 300;
                }
            }

            // Prefer playing tiles that have a pip matching our smallest pip count to diversify
            int minPipCount = 7;
            for (int i = 0; i < 7; i++)
            {
                if (pipCounts[i] < minPipCount && pipCounts[i] > 0)
                    minPipCount = pipCounts[i];
            }
            if (pipCounts[tile.LowPip.Value] == minPipCount || (!tile.IsDouble && pipCounts[tile.HighPip.Value] == minPipCount))
                score += 20;

            if (score > bestScore)
            {
                bestScore = score;
                bestMove = move;
            }
        }

        // Fallback to first legal move if no best move found (shouldn't happen)
        if (bestMove == null)
        {
            bestMove = legalMoves[0];
        }

        return bestMove;
    }

    private int CountMatchingAfterPlay(BonesHand hand, BonesTile playedTile, int leftPip, int rightPip)
    {
        int count = 0;
        foreach (var tile in hand.Tiles)
        {
            // Skip the tile we're playing
            if (tile.LowPip.Value == playedTile.LowPip.Value && 
                tile.HighPip.Value == playedTile.HighPip.Value && 
                tile.IsDouble == playedTile.IsDouble)
                continue;

            if (tile.LowPip.Value == leftPip || tile.HighPip.Value == leftPip ||
                tile.LowPip.Value == rightPip || tile.HighPip.Value == rightPip)
                count++;
        }
        return count;
    }
}
